import{_ as e,o,c as t,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"第六部分 · 分布式系统","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/index.md","filePath":"distributed/README.md","lastUpdated":1788475713000}'),s={name:"distributed/index.md"};function r(l,a,i,p,c,d){return o(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="第六部分-·-分布式系统" tabindex="-1">第六部分 · 分布式系统 <a class="header-anchor" href="#第六部分-·-分布式系统" aria-label="Permalink to &quot;第六部分 · 分布式系统&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>分布式系统 = N 台独立计算机通过通信协作<strong>表现为一个整体</strong>。核心挑战：部分故障 (partial failure)、不可靠网络 (unreliable network)、无共享时钟 (no shared clock)、并发控制 (concurrency)。无数论文在解决同一个问题：<strong>怎么让不同机器对一个值&quot;达成共识&quot;</strong>。</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><p>API 高层：用户 <code>POST /api/order</code>，看似一个简单 RPC 调用——</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ HTTP 请求 ]</span></span>
<span class="line"><span>    └─ 网络 → 负载均衡 → API gateway (无状态) → Order Service (无状态)</span></span>
<span class="line"><span>           └─ 强一致状态机 Raft 复制组 (5 节点，多数派持久化)</span></span>
<span class="line"><span>                  └─ Paxos 协议选出一个 leader</span></span>
<span class="line"><span>                         └─ 所有写入串行化进 Multi-Paxos 实例</span></span>
<span class="line"><span>                                └─ WAL 落盘 fsync</span></span>
<span class="line"><span>                                       └─ 此时才返回 200 OK 给客户端</span></span></code></pre></div><p>请求每一次成功 commit 都涉及：网络多跳、consensus 算法、持久化、leader election / membership change。这一层是<strong>字面意义决定高可用或永久数据丢失的关键</strong>——李飞飞团队 2017 Spanner 论文证明了 CRDT 不足以做银行账户；Apple WebObjects 2007 事故证明了 Paxos 错误实施可直接让集群锁死 30 小时。理解分布式系统不是&quot;加更多机器让事务变快&quot;，而是&quot;在 partial failure 下证明你的 promise 仍 hold&quot;。</p><h2 id="_6-个章节" tabindex="-1">6 个章节 <a class="header-anchor" href="#_6-个章节" aria-label="Permalink to &quot;6 个章节&quot;">​</a></h2><ul><li><a href="./concepts/">基础概念</a> — CAP / PACELC / BASE / 一致性等级 / 故障模型</li><li><a href="./consensus/">共识</a> — Paxos / Multi-Paxos / Raft / ZAB</li><li><a href="./replication/">复制</a> — 主从 / 多主 / 无主 / CRDT</li><li><a href="./transactions">分布式事务</a> — 2PC / Saga / TCC / Outbox / Spanner</li><li><a href="./clock/">时钟与顺序</a> — Logical Clock / Vector Clock / HLC / TrueTime / DAG</li><li><a href="./fault/">分布式存储与容错</a> — Quorum / Erasure Coding / 调度器</li></ul><p>读完应能回答：</p><ol><li>Paxos vs Raft vs ZAB 的核心差异（leader election、log replication、membership change）</li><li>Quorum 为什么 W+R&gt;N 是必要而非充分条件</li><li>CRDT 如何无 conflict merge，与 serializability 的代价</li><li>Vector clock 怎么检测并发写、HLC 怎么无 GPS 提供 causal consistency</li><li>Erasure code RS(10,4) vs 3 副本在存储与可用性的折中</li><li>Google Spanner 用 TrueTime 实现 external consistency 的代价 (commit wait)</li><li>2PC 协调者崩溃为什么阻塞、Saga 为什么拿不到原子性、Outbox 如何保证&quot;写库+发事件&quot;原子</li></ol><h2 id="历史-1-1978-lamport-time-clocks" tabindex="-1">历史 1：1978 Lamport &quot;Time, Clocks&quot; <a class="header-anchor" href="#历史-1-1978-lamport-time-clocks" aria-label="Permalink to &quot;历史 1：1978 Lamport &quot;Time, Clocks&quot;&quot;">​</a></h2><p>奠定整个领域基础——&quot;分布式系统中事件顺序不能靠 wall clock，要靠 happens-before&quot;。Lamport 之后所有 paper 都假设这个 partial order 是基础事实。</p><h2 id="历史-2-1989-paxos-1998-lamport-拖了-9-年才发" tabindex="-1">历史 2：1989 Paxos, 1998 Lamport 拖了 9 年才发 <a class="header-anchor" href="#历史-2-1989-paxos-1998-lamport-拖了-9-年才发" aria-label="Permalink to &quot;历史 2：1989 Paxos, 1998 Lamport 拖了 9 年才发&quot;">​</a></h2><p>1989 Lamport 发现 Paxos 但写成希腊神话式 paper &quot;The Part-Time Parliament&quot;，没人懂；1998 重写 &quot;Paxos Made Simple&quot; 才被 Google 采纳成 Chubby。Raft 2014 由 Diego Ongaro 在 Stanford 写完为了&quot;比 Paxos 更易懂&quot;。</p><h2 id="历史-3-aws-dynamo-2007" tabindex="-1">历史 3：AWS Dynamo (2007) <a class="header-anchor" href="#历史-3-aws-dynamo-2007" aria-label="Permalink to &quot;历史 3：AWS Dynamo (2007)&quot;">​</a></h2><p>Berkley Amazon Dynamo 论文发表，业界第一个大规模 AP + Vector Clock + Hinted Handoff 的工业系统。Cassandra、Riak、Voldemort 都跟。</p><h2 id="历史-4-google-spanner-2012" tabindex="-1">历史 4：Google Spanner (2012) <a class="header-anchor" href="#历史-4-google-spanner-2012" aria-label="Permalink to &quot;历史 4：Google Spanner (2012)&quot;">​</a></h2><p>第一次工业实现 external consistency —— 靠 GPS / 原子钟 TrueTime API 实现跨数据中心线性化。Sharding + TrueTime + 2PC 让 Google Ads 全球任意节点写入都能 audit。Apple、CockroachDB 都跟 SR 树。</p><hr><p>下一节 → <a href="./concepts/">基础概念</a></p>`,21)])])}const m=e(s,[["render",r]]);export{h as __pageData,m as default};
